library IEEE;
use     IEEE.STD_LOGIC_1164.ALL;
use     IEEE.numeric_std.ALL;

library asylum;
use     asylum.sbi_pkg.all;
use     asylum.pwm_pkg.all;
use     asylum.PWM_csr_pkg.all;

entity sbi_PWM is
  generic(
    NAME                  : string  := "";
    USER_DEFINE_PRESCALER : boolean := true;                         -- Prescaler register writable by software
    PRESCALER_RATIO       : std_logic_vector(8-1 downto 0) := x"C2"  -- Default value for prescaler ratio (1 kHz with a 50 MHz clock and period = 0xFF)
    );
  port   (
    clk_i            : in  std_logic;
    arst_b_i         : in  std_logic; -- asynchronous reset

    -- Bus
    sbi_ini_i        : in  sbi_ini_t;
    sbi_tgt_o        : out sbi_tgt_t;

    -- PWM Output
    pwm_o            : out std_logic
    );

end entity sbi_PWM;

architecture rtl of sbi_PWM is

  signal   sw2hw                  : PWM_sw2hw_t;

begin  -- architecture rtl

  -----------------------------------------------------------------------------
  -- CSR Instance
  -----------------------------------------------------------------------------
  ins_csr : PWM_registers
  generic map
  ( MODULE_NAME           => NAME
   ,USER_DEFINE_PRESCALER => USER_DEFINE_PRESCALER
   ,PRESCALER_RATIO       => PRESCALER_RATIO
    )
  port map
  (
    clk_i     => clk_i
   ,arst_b_i  => arst_b_i
   ,sbi_ini_i => sbi_ini_i
   ,sbi_tgt_o => sbi_tgt_o
   ,sw2hw_o   => sw2hw
  );

  -----------------------------------------------------------------------------
  -- PWM Core
  -----------------------------------------------------------------------------
  ins_pwm_core : pwm_core
    generic map
    ( PRESCALER_WIDTH       => 8
     ,COUNTER_WIDTH         => 8
     )
    port map
    ( clk_i                 => clk_i
     ,arst_b_i              => arst_b_i
     ,cfg_enable_i          => sw2hw.cfg.enable(0)
     ,cfg_prescaler_ratio_i => sw2hw.prescaler.ratio
     ,cfg_period_i          => sw2hw.period.value
     ,cfg_duty_i            => sw2hw.duty.value
     ,pwm_o                 => pwm_o
    );

end architecture rtl;
